CREATE TABLE telegram_identities (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    family_id INTEGER,
    child_id INTEGER,
    telegram_user_id BIGINT NOT NULL,
    role VARCHAR(20) NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    linked_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    unlinked_at TIMESTAMP WITH TIME ZONE
);
CREATE UNIQUE INDEX uq_telegram_identity_active_user ON telegram_identities(telegram_user_id, is_active);
CREATE TABLE telegram_child_invitations (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, family_id INTEGER NOT NULL, child_id INTEGER NOT NULL, secret_digest VARCHAR(128) NOT NULL UNIQUE, expires_at TIMESTAMP WITH TIME ZONE NOT NULL, revoked_at TIMESTAMP WITH TIME ZONE, consumed_at TIMESTAMP WITH TIME ZONE, issued_by VARCHAR(255) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE telegram_callback_actions (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, family_id INTEGER NOT NULL, identity_id INTEGER, action VARCHAR(32) NOT NULL, target_id BIGINT NOT NULL, secret_digest VARCHAR(128) NOT NULL UNIQUE, expires_at TIMESTAMP WITH TIME ZONE NOT NULL, consumed_at TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE telegram_webhook_updates (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, update_id BIGINT NOT NULL UNIQUE, received_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, processed_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE telegram_security_audit_events (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, family_id INTEGER, child_id INTEGER, identity_id INTEGER, event_type VARCHAR(64) NOT NULL, actor_reference VARCHAR(255), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
